int sz[MAXN];                     // 처음에는 sz[x] = 1 (루트에서만 의미가 있음)
bool unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;
    if (sz[a] < sz[b]) swap(a, b);  // a가 더 큰 쪽(같으면 그대로)
    p[b] = a;                     // 작은 트리를 큰 트리 밑에
    sz[a] += sz[b];
    return true;
}

